(async () => {
  // 檢查 args[0] 是否爲 "off"，表示效果被刪除
  if (args[0] !== "off") {
    console.log("❌ 宏未觸發：args[0] 不是 'off'，當前值爲", args[0]);
    return;
  }

  // 獲取目標 Token 和 Actor
  const tokenId = args[1]?.tokenId || args[1]?.token?.id;
  const token = canvas.tokens.get(tokenId);
  const actor = token?.actor;
  if (!actor) {
    console.log("❌ 未找到目標 Actor，無法繼續執行宏");
    return;
  }

  console.log("✅ 成功獲取 Actor：", actor.name);

  // 查找名爲“艾伐黑觸手 Black Tentacles (In Aura)”的效果
  const auraEffect = actor.effects.find(e => e.label === "艾伐黑觸手 Black Tentacles (In Aura)");
  if (!auraEffect) {
    console.log("⚠️ 未找到 '艾伐黑觸手 Black Tentacles (In Aura)' 效果");
    return;
  }

  // 刪除該效果
  await auraEffect.delete();
  console.log("🧹 已成功刪除 '艾伐黑觸手 Black Tentacles (In Aura)' 效果");
})();
